import {disableCommentsAsDOMContainers} from 'shared/ReactFeatureFlags';
import {
  ELEMENT_NODE,
  COMMENT_NODE,
  DOCUMENT_NODE,
  DOCUMENT_FRAGMENT_NODE,
} from './HTMLNodeType';

